ayat = [
    "﴿اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ [البقرة: 255]",
    "﴿اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ ۚ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ ۖ الْمِصْبَاحُ فِي زُجَاجَةٍ ۖ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَارَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ ۚ نُورٌ عَلَىٰ نُورٍ ۗ يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاءُ ۚ وَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ ۗ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾ [النور: 35]",
    "﴿اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ ۚ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [الحج: 75]",
    "﴿اللَّهُ يَدْعُو إِلَىٰ دَارِ السَّلَامِ وَيَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ﴾ [يونس: 25]",
    "﴿اللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾ [النحل: 19]",
    "﴿اللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾ [البقرة: 20]",
    "﴿اللَّهُ عَلَىٰ كُلِّ نَفْسٍ حَفِيظٌ﴾ [هود: 57]",
    "﴿اللَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ﴾ [المجادلة: 6]",
    "﴿اللَّهُ عَلَىٰ كُلِّ شَيْءٍ وَكِيلٌ﴾ [النساء: 85]",
    "﴿اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرٌ﴾ [الكهف: 45]",
    "﴿اللَّهُ عَلَىٰ كُلِّ شَيْءٍ حَفِيظٌ﴾ [هود: 57]",
    "﴿وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰ أَن تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَّكُمْ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ﴾ [البقرة: 216]",
    "﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا * إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ [الشرح: 5-6]",
    "﴿فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ﴾ [البقرة: 152]",
    "﴿إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ [البقرة: 153]",
    "﴿وَقُل رَّبِّ زِدْنِي عِلْمًا﴾ [طه: 114]",
    "﴿الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ اللَّهِ ۗ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾ [الرعد: 28]",
    "﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ﴾ [الرعد: 11]",
    "﴿قُل لَّن يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا هُوَ مَوْلَانَا وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ﴾ [التوبة: 51]",
    "﴿رَبِّ اشْرَحْ لِي صَدْرِي * وَيَسِّرْ لِي أَمْرِي﴾ [طه: 25-26]",
    "﴿وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ﴾ [الأعراف: 156]",
    "﴿إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ﴾ [الشعراء: 62]",
    "﴿وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا * وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ﴾ [الطلاق: 2-3]",
    "﴿وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ﴾ [الطلاق: 3]",
    "﴿رَّبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ الْوَهَّابُ﴾ [آل عمران: 8]",
    "﴿إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ﴾ [آل عمران: 159]",
    "﴿فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ﴾ [البقرة: 186]",
    "﴿لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا﴾ [الزمر: 53]",
    "﴿إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ﴾ [إبراهيم: 39]",
    "﴿رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ﴾ [الأعراف: 126]"
]

ahadith = [
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من قال حين يصبح وحين يمسي: سبحان الله وبحمده مائة مرة، لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ما قال أو زاد عليه) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من قال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، في يوم مائة مرة، كانت له عدل عشر رقاب، وكتبت له مائة حسنة، ومحيت عنه مائة سيئة، وكان له من الله عز وجل حرزاً من الشيطان يومه ذلك حتى يمسي) [البخاري ومسلم]",
    "عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من قال: سبحان الله وبحمده، في يوم مائة مرة، حطت خطاياه وإن كانت مثل زبد البحر) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من قال: سبحان الله وبحمده، سبحان الله العظيم، في يوم مائة مرة، لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ما قال أو زاد عليه) [البخاري ومسلم]",
    "عن عمر بن الخطاب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى) [البخاري ومسلم]",
    "عن النعمان بن بشير رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (مثل المؤمنين في توادهم وتراحمهم وتعاطفهم مثل الجسد، إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من لا يَرحم لا يُرحم) [البخاري ومسلم]",
    "عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (الكلمة الطيبة صدقة) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له) [مسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من سلك طريقاً يلتمس فيه علماً سهّل الله له به طريقاً إلى الجنة) [مسلم]",
    "عن عبد الله بن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: (المسلم من سلم المسلمون من لسانه ويده) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (تبسمك في وجه أخيك صدقة) [الترمذي، صحيح]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (الدين النصيحة) [مسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من لا يشكر الناس لا يشكر الله) [الترمذي، صحيح]",
    "عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (يسروا ولا تعسروا، وبشروا ولا تنفروا) [البخاري ومسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير) [مسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من نفس عن مؤمن كربة من كرب الدنيا نفس الله عنه كربة من كرب يوم القيامة) [مسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (الدعاء هو العبادة) [الترمذي، صحيح]",
    "عن سهل بن سعد رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من كان في حاجة أخيه كان الله في حاجته) [البخاري ومسلم]",
    "عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر) [مسلم]",
    "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (من ستر مسلماً ستره الله في الدنيا والآخرة) [مسلم]",
    "عن أبي ذر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (اتق الله حيثما كنت، وأتبع السيئة الحسنة تمحها، وخالق الناس بخلق حسن) [الترمذي، حسن]",
]

adhkar = [
    "أستغفر الله العظيم وأتوب إليه",
    "سبحان الله وبحمده، سبحان الله العظيم",
    "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير",
    "اللهم صل وسلم على نبينا محمد",
    "سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر",
    "اللهم اغفر لي ولوالدي ولجميع المسلمين والمسلمات",
    "اللهم اجعلني من التوابين واجعلني من المتطهرين",
    "اللهم إني أعوذ بك من الهم والحزن، وأعوذ بك من العجز والكسل، وأعوذ بك من الجبن والبخل، وأعوذ بك من غلبة الدين وقهر الرجال",
    "اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك علي، وأبوء بذنبي، فاغفر لي، فإنه لا يغفر الذنوب إلا أنت",
    "اللهم بك أصبحنا وبك أمسينا، وبك نحيا وبك نموت وإليك النشور",
    "اللهم إني أصبحت أشهدك وأشهد حملة عرشك وملائكتك وجميع خلقك أنك أنت الله لا إله إلا أنت وحدك لا شريك لك، وأن محمدًا عبدك ورسولك",
    "اللهم ما أصبح بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك، فلك الحمد ولك الشكر",
    "اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري، لا إله إلا أنت",
    "اللهم إني أعوذ بك من الكفر والفقر، وأعوذ بك من عذاب القبر، لا إله إلا أنت",
    "اللهم إني أسألك العفو والعافية في الدنيا والآخرة",
    "اللهم اجعلني من الذين إذا أحسنوا استبشروا، وإذا أساؤوا استغفروا",
    "اللهم اجعلني لك شاكراً، لك ذاكراً، لك مخبتاً، لك أواهًا منيبًا",
    "اللهم اجعل آخر كلامنا من الدنيا لا إله إلا الله",
    "اللهم اجعلنا من الذاكرين الله كثيراً والذاكرات",
    "اللهم إني أعوذ بك من زوال نعمتك وتحول عافيتك وفجاءة نقمتك وجميع سخطك",
    "اللهم إني أسألك علماً نافعاً، ورزقاً طيباً، وعملاً متقبلاً",
    "اللهم اجعل القرآن ربيع قلبي ونور صدري وجلاء حزني وذهاب همي",
    "اللهم ارزقني قلبًا سليمًا ولسانًا صادقًا",
    "اللهم اجعل هذا اليوم خيرًا من أمس، واغفر لي ما مضى، وبارك لي فيما هو آتٍ",
    "اللهم إني أعوذ بك من شر نفسي ومن شر الشيطان وشركه",
]

quran_duas = [
    "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ [البقرة:127]",
    "رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ [البقرة:128]",
    "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201]",
    "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ [البقرة:250]",
    "رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا [البقرة:286]",
    "رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا [البقرة:286]",
    "رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ [البقرة:286]",
    "رَبَّنَا وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ [البقرة:286]",
    "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً [آل عمران:8]",
    "رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ [آل عمران:9]",
    "رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ [آل عمران:53]",
    "رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا [آل عمران:147]",
    "رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ [آل عمران:191]",
    "رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا [آل عمران:193]",
    "رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ [آل عمران:193]",
    "رَبِّ اشْرَحْ لِي صَدْرِي [طه:25]",
    "رَبِّ زِدْنِي عِلْمًا [طه:114]",
    "رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا [الإسراء:80]",
    "رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ [الشعراء:83]",
    "رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ [التحريم:11]",
    "رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً [آل عمران:38]",
    "رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ [الأنبياء:89]",
    "رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ [الأعراف:23]",
    "رَبَّنَا أَخْرِجْنَا مِنْ هَٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا [النساء:75]",
    "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ [الأحقاف:15]",
    "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا [الفرقان:74]",
    "رَبِّ نَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ [القصص:21]",
    "رَبِّ أَنْزِلْنِي مُنْزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ [المؤمنون:29]",
    "رَبِّ إِنِّي مَغْلُوبٌ فَانتَصِرْ [القمر:10]",
]

morning_adhkar = [
    "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ",
    "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ، لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ، لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ، مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ، يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ، وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ، وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ، وَلَا يَئُودُهُ حِفْظُهُمَا، وَهُوَ الْعَلِيُّ الْعَظِيمُ.",
    "قُلْ هُوَ اللَّهُ أَحَدٌ. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ. (يُقرأ كلٌّ مِنْهَا ثلاثَ مرّاتٍ)",
    "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.",
    "اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.",
    "اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ، وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ. (تُقال أربعَ مرّاتٍ)",
    "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. (ثلاثَ مرّاتٍ)",
    "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. (ثلاثَ مرّاتٍ)",
    "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ. (سبعَ مرّاتٍ)",
    "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ.",
    "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ. (يُستحبّ مائة مرةٍ أو كثيراً)",
    "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ."
]

evening_adhkar = [
    "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ",
    "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ، لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ، لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ، مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ، يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ، وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ، وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ، وَلَا يَئُودُهُ حِفْظُهُمَا، وَهُوَ الْعَلِيُّ الْعَظِيمُ.",
    "قُلْ هُوَ اللَّهُ أَحَدٌ. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ. (يُقرأ كلٌّ مِنْهَا ثلاثَ مرّاتٍ)",
    "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. (يُقال تفصيلاً كما ورد)",
    "اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ.",
    "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.",
    "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا.",
    "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ. (يُستحبّ مائة مرةٍ أو كثيراً)",
    "اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ."
]